/** static void OpponentHandleGetRawMonData(void) */
export function OpponentHandleGetRawMonData(): any {
  let battleMon: any = null;
      let src: any =gEnemyParty[gBattlerPartyIndexes[gActiveBattler]] + gBattleBufferA[gActiveBattler][1];
      let dst: any =battleMon + gBattleBufferA[gActiveBattler][1];
      let i: any = null;

      for (i = 0; i < gBattleBufferA[gActiveBattler][2]; i++)
          dst[i] = src[i];

      BtlController_EmitDataTransfer(B_COMM_TO_ENGINE, gBattleBufferA[gActiveBattler][2], dst);
      OpponentBufferExecCompleted();
}

/** static void OpponentHandleSetMonData(void) */
export function OpponentHandleSetMonData(): any {
  let monToCheck: any = null;
      let i: any = null;

      if (gBattleBufferA[gActiveBattler][2] == 0)
      {
          SetOpponentMonData(gBattlerPartyIndexes[gActiveBattler]);
      }
      else
      {
          monToCheck = gBattleBufferA[gActiveBattler][2];
          for (i = 0; i < PARTY_SIZE; i++)
          {
              if (monToCheck & 1)
                  SetOpponentMonData(i);
              monToCheck >>= 1;
          }
      }
      OpponentBufferExecCompleted();
}

/** static void SetOpponentMonData(u8 monId) */
