/** static void DoSwitchOutAnimation(void) */
export function DoSwitchOutAnimation(): any {
  switch (gBattleSpritesDataPtr.healthBoxesData[gActiveBattler].animationState)
      {
      case 0:
          if (gBattleSpritesDataPtr.battlerData[gActiveBattler].behindSubstitute)
              InitAndLaunchSpecialAnimation(gActiveBattler, gActiveBattler, gActiveBattler, B_ANIM_SUBSTITUTE_TO_MON);

          gBattleSpritesDataPtr.healthBoxesData[gActiveBattler].animationState = 1;
          break;
      case 1:
          if (!gBattleSpritesDataPtr.healthBoxesData[gActiveBattler].specialAnimActive)
          {
              gBattleSpritesDataPtr.healthBoxesData[gActiveBattler].animationState = 0;
              InitAndLaunchSpecialAnimation(gActiveBattler, gActiveBattler, gActiveBattler, B_ANIM_SWITCH_OUT_OPPONENT_MON);
              gBattlerControllerFuncs[gActiveBattler] = FreeMonSpriteAfterSwitchOutAnim;
          }
          break;
      }
}

/** static void OpponentHandleDrawTrainerPic(void) */
export function OpponentHandleDrawTrainerPic(): any {
  let trainerPicId: any = null;
      let xPos: any = null;

      if (gBattleTypeFlags & BATTLE_TYPE_SECRET_BASE)
      {
          trainerPicId = GetSecretBaseTrainerPicIndex();
      }
      else if (gTrainerBattleOpponent_A == TRAINER_FRONTIER_BRAIN)
      {
          trainerPicId = GetFrontierBrainTrainerPicIndex();
      }
      else if (gBattleTypeFlags & BATTLE_TYPE_TRAINER_HILL)
      {
          if (gBattleTypeFlags & BATTLE_TYPE_TWO_OPPONENTS)
          {
              if (gActiveBattler == 1)
                  trainerPicId = GetTrainerHillTrainerFrontSpriteId(gTrainerBattleOpponent_A);
              else
                  trainerPicId = GetTrainerHillTrainerFrontSpriteId(gTrainerBattleOpponent_B);
          }
          else
          {
              trainerPicId = GetTrainerHillTrainerFrontSpriteId(gTrainerBattleOpponent_A);
          }
      }
      else if (gBattleTypeFlags & BATTLE_TYPE_FRONTIER)
      {
          if (gBattleTypeFlags & (BATTLE_TYPE_TWO_OPPONENTS | BATTLE_TYPE_TOWER_LINK_MULTI))
          {
              if (gActiveBattler == 1)
                  trainerPicId = GetFrontierTrainerFrontSpriteId(gTrainerBattleOpponent_A);
              else
                  trainerPicId = GetFrontierTrainerFrontSpriteId(gTrainerBattleOpponent_B);
          }
          else
          {
              trainerPicId = GetFrontierTrainerFrontSpriteId(gTrainerBattleOpponent_A);
          }
      }
      else if (gBattleTypeFlags & BATTLE_TYPE_EREADER_TRAINER)
      {
          trainerPicId = GetEreaderTrainerFrontSpriteId();
      }
      else if (gBattleTypeFlags & BATTLE_TYPE_TWO_OPPONENTS)
      {
          if (gActiveBattler != 1)
              trainerPicId = gTrainers[gTrainerBattleOpponent_B].trainerPic;
          else
              trainerPicId = gTrainers[gTrainerBattleOpponent_A].trainerPic;
      }
      else
      {
          trainerPicId = gTrainers[gTrainerBattleOpponent_A].trainerPic;
      }

      if (gBattleTypeFlags & (BATTLE_TYPE_MULTI | BATTLE_TYPE_TWO_OPPONENTS))
      {
          if ((GetBattlerPosition(gActiveBattler) & BIT_FLANK) != 0)  
              xPos = 152;
          else  
              xPos = 200;
      }
      else
      {
          xPos = 176;
      }

      DecompressTrainerFrontPic(trainerPicId, gActiveBattler);
      SetMultiuseSpriteTemplateToTrainerBack(trainerPicId, GetBattlerPosition(gActiveBattler));
      gBattlerSpriteIds[gActiveBattler] = CreateSprite(gMultiuseSpriteTemplate,
                                                 xPos,
                                                 (8 - gTrainerFrontPicCoords[trainerPicId].size) * 4 + 40,
                                                 GetBattlerSpriteSubpriority(gActiveBattler));

      gSprites[gBattlerSpriteIds[gActiveBattler]].x2 = -DISPLAY_WIDTH;
      gSprites[gBattlerSpriteIds[gActiveBattler]].sSpeedX = 2;
      gSprites[gBattlerSpriteIds[gActiveBattler]].oam.paletteNum = IndexOfSpritePaletteTag(gTrainerFrontPicPaletteTable[trainerPicId].tag);
      gSprites[gBattlerSpriteIds[gActiveBattler]].oam.affineParam = trainerPicId;
      gSprites[gBattlerSpriteIds[gActiveBattler]].callback = SpriteCB_TrainerSlideIn;

      gBattlerControllerFuncs[gActiveBattler] = CompleteOnBattlerSpriteCallbackDummy;
}

