/** static void OpponentHandleMoveAnimation(void) */
export function OpponentHandleMoveAnimation(): any {
  if (!IsBattleSEPlaying(gActiveBattler))
      {
          let move: any = gBattleBufferA[gActiveBattler][1] | (gBattleBufferA[gActiveBattler][2] << 8);

          gAnimMoveTurn = gBattleBufferA[gActiveBattler][3];
          gAnimMovePower = gBattleBufferA[gActiveBattler][4] | (gBattleBufferA[gActiveBattler][5] << 8);
          gAnimMoveDmg = gBattleBufferA[gActiveBattler][6] | (gBattleBufferA[gActiveBattler][7] << 8) | (gBattleBufferA[gActiveBattler][8] << 16) | (gBattleBufferA[gActiveBattler][9] << 24);
          gAnimFriendship = gBattleBufferA[gActiveBattler][10];
          gWeatherMoveAnim = gBattleBufferA[gActiveBattler][12] | (gBattleBufferA[gActiveBattler][13] << 8);
          gAnimDisableStructPtr =gBattleBufferA[gActiveBattler][16];
          gTransformedPersonalities[gActiveBattler] = gAnimDisableStructPtr.transformedMonPersonality;
          if (IsMoveWithoutAnimation(move, gAnimMoveTurn))  
          {
              OpponentBufferExecCompleted();
          }
          else
          {
              gBattleSpritesDataPtr.healthBoxesData[gActiveBattler].animationState = 0;
              gBattlerControllerFuncs[gActiveBattler] = OpponentDoMoveAnimation;
          }
      }
}

/** static void OpponentDoMoveAnimation(void) */
export function OpponentDoMoveAnimation(): any {
  let move: any = gBattleBufferA[gActiveBattler][1] | (gBattleBufferA[gActiveBattler][2] << 8);
      let multihit: any = gBattleBufferA[gActiveBattler][11];

      switch (gBattleSpritesDataPtr.healthBoxesData[gActiveBattler].animationState)
      {
      case 0:
          if (gBattleSpritesDataPtr.battlerData[gActiveBattler].behindSubstitute
              && !gBattleSpritesDataPtr.battlerData[gActiveBattler].flag_x8)
          {
              gBattleSpritesDataPtr.battlerData[gActiveBattler].flag_x8 = 1;
              InitAndLaunchSpecialAnimation(gActiveBattler, gActiveBattler, gActiveBattler, B_ANIM_SUBSTITUTE_TO_MON);
          }
          gBattleSpritesDataPtr.healthBoxesData[gActiveBattler].animationState = 1;
          break;
      case 1:
          if (!gBattleSpritesDataPtr.healthBoxesData[gActiveBattler].specialAnimActive)
          {
              SetBattlerSpriteAffineMode(ST_OAM_AFFINE_OFF);
              DoMoveAnim(move);
              gBattleSpritesDataPtr.healthBoxesData[gActiveBattler].animationState = 2;
          }
          break;
      case 2:
          gAnimScriptCallback();
          if (!gAnimScriptActive)
          {
              SetBattlerSpriteAffineMode(ST_OAM_AFFINE_NORMAL);
              if (gBattleSpritesDataPtr.battlerData[gActiveBattler].behindSubstitute && multihit < 2)
              {
                  InitAndLaunchSpecialAnimation(gActiveBattler, gActiveBattler, gActiveBattler, B_ANIM_MON_TO_SUBSTITUTE);
                  gBattleSpritesDataPtr.battlerData[gActiveBattler].flag_x8 = 0;
              }
              gBattleSpritesDataPtr.healthBoxesData[gActiveBattler].animationState = 3;
          }
          break;
      case 3:
          if (!gBattleSpritesDataPtr.healthBoxesData[gActiveBattler].specialAnimActive)
          {
              CopyAllBattleSpritesInvisibilities();
              TrySetBehindSubstituteSpriteBit(gActiveBattler, gBattleBufferA[gActiveBattler][1] | (gBattleBufferA[gActiveBattler][2] << 8));
              gBattleSpritesDataPtr.healthBoxesData[gActiveBattler].animationState = 0;
              OpponentBufferExecCompleted();
          }
          break;
      }
}

