/** static void OpponentHandleIntroTrainerBallThrow(void) */
export function OpponentHandleIntroTrainerBallThrow(): any {
  let taskId: any = null;

      SetSpritePrimaryCoordsFromSecondaryCoords(gSprites[gBattlerSpriteIds[gActiveBattler]]);

      gSprites[gBattlerSpriteIds[gActiveBattler]].data[0] = 35;
      gSprites[gBattlerSpriteIds[gActiveBattler]].data[2] = 280;
      gSprites[gBattlerSpriteIds[gActiveBattler]].data[4] = gSprites[gBattlerSpriteIds[gActiveBattler]].y;
      gSprites[gBattlerSpriteIds[gActiveBattler]].callback = StartAnimLinearTranslation;

      StoreSpriteCallbackInData6(gSprites[gBattlerSpriteIds[gActiveBattler]], SpriteCB_FreeOpponentSprite);

      taskId = CreateTask(Task_StartSendOutAnim, 5);
      gTasks[taskId].data[0] = gActiveBattler;

      if (gBattleSpritesDataPtr.healthBoxesData[gActiveBattler].partyStatusSummaryShown)
          gTasks[gBattlerStatusSummaryTaskId[gActiveBattler]].func = Task_HidePartyStatusSummary;

      gBattleSpritesDataPtr.animationData.introAnimActive = TRUE;
      gBattlerControllerFuncs[gActiveBattler] = OpponentDummy;
}

/** static void SpriteCB_FreeOpponentSprite(struct Sprite *sprite) */
export function SpriteCB_FreeOpponentSprite(sprite: any): any {
  FreeTrainerFrontPicPalette(sprite.oam.affineParam);
      FreeSpriteOamMatrix(sprite);
      DestroySprite(sprite);
}

/** static void Task_StartSendOutAnim(u8 taskId) */
export function Task_StartSendOutAnim(taskId: any): any {
  let savedActiveBank: any = gActiveBattler;

      gActiveBattler = gTasks[taskId].data[0];
      if (!IsDoubleBattle() || (gBattleTypeFlags & BATTLE_TYPE_MULTI))
      {
          gBattleBufferA[gActiveBattler][1] = gBattlerPartyIndexes[gActiveBattler];
          StartSendOutAnim(gActiveBattler, FALSE);
      }
      else if ((gBattleTypeFlags & BATTLE_TYPE_TWO_OPPONENTS))
      {
          gBattleBufferA[gActiveBattler][1] = gBattlerPartyIndexes[gActiveBattler];
          StartSendOutAnim(gActiveBattler, FALSE);
      }
      else
      {
          gBattleBufferA[gActiveBattler][1] = gBattlerPartyIndexes[gActiveBattler];
          StartSendOutAnim(gActiveBattler, FALSE);
          gActiveBattler ^= BIT_FLANK;
          gBattleBufferA[gActiveBattler][1] = gBattlerPartyIndexes[gActiveBattler];
          StartSendOutAnim(gActiveBattler, FALSE);
          gActiveBattler ^= BIT_FLANK;
      }
      gBattlerControllerFuncs[gActiveBattler] = Intro_TryShinyAnimShowHealthbox;
      gActiveBattler = savedActiveBank;
      DestroyTask(taskId);
}

/** static void OpponentHandleDrawPartyStatusSummary(void) */
export function OpponentHandleDrawPartyStatusSummary(): any {
  if (gBattleBufferA[gActiveBattler][1] != 0 && GetBattlerSide(gActiveBattler) == B_SIDE_PLAYER)
      {
          OpponentBufferExecCompleted();
      }
      else
      {
          gBattleSpritesDataPtr.healthBoxesData[gActiveBattler].partyStatusSummaryShown = 1;

          if (gBattleBufferA[gActiveBattler][2] != 0)
          {
              if (gBattleSpritesDataPtr.healthBoxesData[gActiveBattler].opponentDrawPartyStatusSummaryDelay < 2)
              {
                  gBattleSpritesDataPtr.healthBoxesData[gActiveBattler].opponentDrawPartyStatusSummaryDelay++;
                  return;
              }
              else
              {
                  gBattleSpritesDataPtr.healthBoxesData[gActiveBattler].opponentDrawPartyStatusSummaryDelay = 0;
              }
          }

          gBattlerStatusSummaryTaskId[gActiveBattler] = CreatePartyStatusSummarySprites(gActiveBattler,gBattleBufferA[gActiveBattler][4], gBattleBufferA[gActiveBattler][1], gBattleBufferA[gActiveBattler][2]);
          gBattleSpritesDataPtr.healthBoxesData[gActiveBattler].partyStatusDelayTimer = 0;

          if (gBattleBufferA[gActiveBattler][2] != 0)
              gBattleSpritesDataPtr.healthBoxesData[gActiveBattler].partyStatusDelayTimer = 93;

          gBattlerControllerFuncs[gActiveBattler] = EndDrawPartyStatusSummary;
      }
}

/** static void EndDrawPartyStatusSummary(void) */
export function EndDrawPartyStatusSummary(): any {
  if (gBattleSpritesDataPtr.healthBoxesData[gActiveBattler].partyStatusDelayTimer++ > 92)
      {
          gBattleSpritesDataPtr.healthBoxesData[gActiveBattler].partyStatusDelayTimer = 0;
          OpponentBufferExecCompleted();
      }
}

